import { encodePrivateText } from "../../security/private-text.js";
import { privateByteLength } from "../../security/private-bytes.js";
import { privateJsonStringify } from "../../security/private-json.js";
import { isIP } from "node:net";
import { defineSchema } from "../../schemas/index.js";
import { snapshotBoundedJsonValue } from "../../schemas/json-value.js";
import { verifyHostedRuntimeSourceBinding } from "./runtime-source-binding.js";
const getIdentifierSchema = defineSchema((v) => v.string().regex(/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/));
/** The identifier rule shared by executor bindings, such as `brokerInstanceId`. */
export const getHostedExecutorIdentifierSchema = getIdentifierSchema;
const getAllocationIdSchema = defineSchema((v) => v.string().regex(/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/));
