/** Trusted source owner, independent of the invocation's application project. */
export const getHostedExecutorOwnerSchema = defineSchema((v) => v.discriminatedUnion("scopeKind", [
    v.object({ scopeKind: v.literal("global"), serviceName: v.string().min(1).max(128) }).strict(),
    v.object({ scopeKind: v.literal("project"), projectId: getIdentifierSchema() }).strict(),
]));
const getExecutionProfileSchema = defineSchema((v) => v.enum(["project-tools", "http"]));
/** The control plane injects authenticated brokerInstanceId; callers cannot submit it here. */
export const getHostedExecutorAllocationRequestSchema = defineSchema((v) => v.object({
    allocationId: getAllocationIdSchema(),
    invocationId: getAllocationIdSchema(),
    owner: getHostedExecutorOwnerSchema(),
    source: getHostedExecutorSourceSchema(),
    executionProfile: getExecutionProfileSchema().optional(),
    requestedAt: getTimestampSchema(),
    prepareDeadlineAt: getTimestampSchema(),
    hardDeadlineAt: getTimestampSchema(),
}).strict().refine((request) => request.requestedAt < request.prepareDeadlineAt &&
    request.prepareDeadlineAt <= request.hardDeadlineAt));
export const getHostedExecutorBindingSchema = defineSchema((v) => v.object({
    allocationId: getAllocationIdSchema(),
    generation: v.number().int().positive().max(Number.MAX_SAFE_INTEGER),
    invocationId: getAllocationIdSchema(),
    brokerInstanceId: getIdentifierSchema(),
    owner: getHostedExecutorOwnerSchema(),
    source: getHostedExecutorSourceSchema(),
    executionProfile: getExecutionProfileSchema().optional(),
}).strict());
export const getHostedExecutorImageSchema = defineSchema((v) => v.string().max(512).regex(/^[a-z0-9][a-z0-9._:/-]*@sha256:[a-f0-9]{64}$/));
export const getHostedExecutorAllocationSchema = defineSchema((v) => v.object({
    binding: getHostedExecutorBindingSchema(),
    phase: v.enum(["preparing", "ready", "terminating", "released"]),
    expiresAt: getTimestampSchema(),
    reason: v.enum([
        "completed",
        "canceled",
        "expired",
        "preparation-timeout",
        "pod-terminated",
        "pod-lost",
        "policy-unavailable",
        "admission-rejected",
    ]).optional(),
    endpoint: v.object({
        address: v.string().max(45).refine((address) => isIP(address) !== 0),
        port: v.literal(8081),
        podUid: getIdentifierSchema(),
        nodeName: getIdentifierSchema(),
        image: getHostedExecutorImageSchema(),
        channelAuthenticated: v.literal(false),
    }).strict().optional(),
}).strict().refine((view) => (view.endpoint === undefined || view.phase === "ready") &&
    ((view.phase === "preparing" || view.phase === "ready")
        ? view.reason === undefined
        : view.reason !== undefined)));
const getAllocationBindingEnvelopeSchema = defineSchema((v) => v.object({ binding: getHostedExecutorBindingSchema() }).passthrough());
/** Fixed diagnostics keep allocator bodies and credentials out of session errors. */
export function parseHostedExecutorData(schema, value) {
    const snapshot = snapshotBoundedJsonValue(value);
    if (!snapshot.success ||
        privateByteLength(encodePrivateText(privateJsonStringify(snapshot.value))) > 32 * 1024) {
        throw new Error("Executor session invalid allocator data");
    }
    const parsed = schema.safeParse(snapshot.value);
    if (!parsed.success)
        throw new Error("Executor session invalid allocator data");
    return parsed.data;
}
